{
  "assumptions": [
    {
      "id": "A1",
      "text": "E is a finite-dimensional real inner-product normed space. Its measurable structure is the Borel structure. Completeness is derived; no positive-dimension or nonempty-sphere assumption is imposed."
    },
    {
      "id": "A2",
      "text": "P is a probability measure on E x real with the canonical product measurable structure, and P.map(fst) is exactly stdGaussian(E)."
    },
    {
      "id": "A3",
      "text": "p is a real polynomial. No coefficient normalization, degree bound, parity, or special generative model is assumed."
    },
    {
      "id": "A4",
      "text": "The actual response function ell(x,y)=y belongs to L2(P). No independence between x and y, and no derivative, mean, potential identity or gradient witness is assumed."
    }
  ],
  "boundaries": [
    "Actual ambient Frechet gradients and unit-sphere projection only; no manifold-gradient API identification.",
    "No transport-cost estimate is added to this interface.",
    "No prescribed numerical operator constants, empirical rate, stochastic process or convergence theorem.",
    "The existing gradient/transport theorem will retain its exact statement and consume this producer.",
    "The source author has read the existing implementation; this authored inventory is not an independent source-topology verdict."
  ],
  "conclusions": [
    {
      "formula": "There exist hf_w: f_w in L2(P), hdf_(w,v): df_(w,v) in L2(P), D:E -> (E ->L H), and M1,M2>0, chosen before rho and before every subsequently evaluated w,u,v.",
      "id": "C1"
    },
    {
      "formula": "For all w,v in E, D(w)v=[df_(w,v)] and HasFDerivAt(F,D(w),w).",
      "id": "C2"
    },
    {
      "formula": "For ||w||<=1, ||D(w)||op<=M1. For ||w||,||u||<=1, ||D(w)-D(u)||op<=M2*||w-u||.",
      "id": "C3",
      "scope": "One and the same D,M1,M2 occurs throughout all conclusions. The constants are existential witnesses, not uniquely determined or dimension-free constants."
    },
    {
      "formula": "For every probability rho on S, every scalar predictor section is rho-integrable, K is Bochner integrable, predictor_rho o fst belongs to L2(P), and [predictor_rho o fst]=m_rho.",
      "id": "C4"
    },
    {
      "formula": "For every such rho and all ambient w, V_rho(w)=2 <m_rho-label,F(w)>_H, with the defining scalar integrand P-integrable.",
      "id": "C5"
    },
    {
      "formula": "For every such rho and ambient w, HasGradientAt(V_rho, 2 D(w)^*(m_rho-label), w), and gradient(V_rho)(w)=2 D(w)^*(m_rho-label).",
      "id": "C6"
    },
    {
      "formula": "For every such rho and unit w, G_rho(w)=2 (D(w)^*(m_rho-label)-<D(w)^*(m_rho-label),w>w).",
      "id": "C7"
    }
  ],
  "definitions": [
    {
      "formula": "gamma=stdGaussian(E); H=L2(P;real); S={w in E : ||w||=1}.",
      "id": "D1",
      "scope": "Gaussian is centered with identity covariance; S has the canonical subtype topology/measurable structure."
    },
    {
      "formula": "f_w(x,y)=p(<w,x>); df_(w,v)(x,y)=pprime(<w,x>)*<v,x>.",
      "id": "D2",
      "scope": "w,v range over all E; these are literal scalar functions."
    },
    {
      "formula": "F(w)=[f_w] in H; label=[ell] in H; D(w)v=[df_(w,v)] in H.",
      "id": "D3",
      "scope": "The theorem produces the required MemLp witnesses and a continuous linear map D(w). Square brackets mean equality classes modulo P-a.e. equality, not a pointwise chosen representative."
    },
    {
      "formula": "For probability rho on S, K(w)=F(w); m_rho=integral_S K(w) d rho(w); predictor_rho(x)=integral_S p(<w,x>) d rho(w).",
      "id": "D4",
      "scope": "The first integral is a Bochner integral in H. All scalar sections and K are proved integrable, and [predictor_rho o fst]=m_rho in H."
    },
    {
      "formula": "V_rho(w)=2 integral_(x,y) (predictor_rho(x)-y)*p(<w,x>) dP(x,y).",
      "id": "D5",
      "scope": "w ranges over every ambient point E; scalar integrability is a conclusion, so the literal potential never relies on the total integral fallback."
    },
    {
      "formula": "g_rho(w)=gradient(V_rho)(w); G_rho(w)=g_rho(w)-<g_rho(w),w>w.",
      "id": "D6",
      "scope": "g is the actual ambient gradient, established by HasGradientAt. For unit w, the second formula is the orthogonal tangent projection; only that domain is asserted for the projected identity."
    }
  ],
  "quantifier_order": "E and its structures; P and probability/Gaussian-marginal hypotheses; polynomial p and actual response-L2 hypothesis; then hf,hdf,D,M1,M2; then all parameter probability laws rho and every evaluation point/direction. There is no law-dependent re-choice of D,M1,M2.",
  "source_kind": "Explicit original library interface extracted from an existing public proof",
  "source_proof_steps": [
    {
      "id": "T1",
      "text": "Use the existing actual Gaussian polynomial L2 derivative producer, which supplies actual scalar feature and directional derivative classes and one operator family with uniform closed-ball bounds."
    },
    {
      "id": "T2",
      "text": "The first-coordinate map is measure preserving. Pull its L2 space isometrically into L2(P), transporting the feature class, derivative operator and the same M1,M2. The pointwise scalar derivative formula is equality in the quotient H."
    },
    {
      "id": "T3",
      "text": "Use the existing Gaussian parameter-average theorem and commute the continuous linear pullback with the Bochner integral. This identifies the actual scalar predictor class with the actual Bochner mean and supplies integrability."
    },
    {
      "id": "T4",
      "text": "The residual class m_rho-label has representative predictor_rho(x)-y P-a.e. The L2 inner-product formula and Cauchy-Schwarz identify the literal potential with 2<m_rho-label,F(w)> and prove its scalar integrability."
    },
    {
      "id": "T5",
      "text": "Apply the existing quadratic-feature derivative theorem to the fixed residual, and use the Hilbert adjoint identity and the gradient/Frechet-derivative equivalence. This proves the ambient gradient formula at every w."
    },
    {
      "id": "T6",
      "text": "Substitute the actual ambient gradient into the literal normal-component subtraction. On the unit sphere this gives the tangent-projection formula."
    }
  ],
  "title": "Actual joint Gaussian polynomial feature, mean and gradient representation"
}
